abstract class Stream(val buf: Buffer)

// Scala 2 only: class FileStream extends { val buf = Buffer(fd) } with Stream(buf)
// Scala 3 drops the early initializer, so the payload is a parameter:
class FileStream(fd: Int) extends Stream(Buffer.forFd(fd))

// cross-compiling alternative: an intermediate class carries the value
abstract class StreamInit(val buf: Buffer) extends Stream(buf)
